## Solutions

1. **Date route**

```javascript
const express = require('express');
const app = express();
const PORT = 3000;

app.get('/date', (req, res) => {
  res.json({ now: new Date().toISOString() });
});

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

**Output:** `Server running on port 3000`

2. **Greeting route**

```javascript
const express = require('express');
const app = express();
app.use(express.json());
const PORT = 3000;

app.post('/greet', (req, res) => {
  const { name } = req.body;
  if (!name) return res.status(400).json({ error: 'Name is required' });
  res.json({ message: `Hello, ${name}!` });
});

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

**Output:** `Server running on port 3000`

3. **PostgreSQL insert**

```javascript
const { Pool } = require('pg');
const pool = new Pool({ connectionString: process.env.DATABASE_URL });

async function insertUser() {
  const client = await pool.connect();
  try {
    await client.query('INSERT INTO users (name) VALUES ($1)', ['Alice']);
    console.log('Inserted user');
  } finally {
    client.release();
  }
}

insertUser().catch(console.error);
```

**Output:** `Inserted user`

4. **Jest test**

```javascript
const request = require('supertest');
const app = require('./app');

describe('POST /greet', () => {
  it('returns a greeting', async () => {
    const response = await request(app)
      .post('/greet')
      .send({ name: 'Bob' });
    expect(response.status).toBe(200);
    expect(response.body.message).toBe('Hello, Bob!');
  });
});
```

**Output:** Test passes with no failures.

5. **Deployment**

Deploy your project to a free host by following the host's documentation, for example Render's guide for Node.js. Set the `DATABASE_URL` environment variable in the host's dashboard.

